from solution import fix_spaces
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(text: str) -> str:
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != " ":
            out.append(text[i])
            i += 1
        else:
            j = i
            while j < n and text[j] == " ":
                j += 1
            run = j - i
            if run > 2:
                out.append("-")
            else:
                out.append("_" * run)
            i = j
    return "".join(out)


def test_spec_example_no_spaces():
    assert fix_spaces("Example") == "Example"


def test_spec_example_single_space():
    assert fix_spaces("Example 1") == "Example_1"


def test_spec_example_leading_single_space():
    assert fix_spaces(" Example 2") == "_Example_2"


def test_spec_example_three_spaces_become_dash():
    assert fix_spaces(" Example   3") == "_Example-3"


def test_two_consecutive_spaces_become_two_underscores():
    assert fix_spaces("a  b") == "a__b"


def test_three_consecutive_spaces_become_single_dash():
    assert fix_spaces("a   b") == "a-b"


def test_four_consecutive_spaces_become_single_dash():
    assert fix_spaces("a    b") == "a-b"


def test_five_consecutive_spaces_become_single_dash():
    assert fix_spaces("a     b") == "a-b"


def test_six_consecutive_spaces_become_single_dash():
    assert fix_spaces("a      b") == "a-b"


def test_only_spaces_runs():
    assert fix_spaces("") == ""
    assert fix_spaces(" ") == "_"
    assert fix_spaces("  ") == "__"
    assert fix_spaces("   ") == "-"
    assert fix_spaces("    ") == "-"
    assert fix_spaces("     ") == "-"
    assert fix_spaces("      ") == "-"


def test_no_spaces_means_unchanged():
    assert fix_spaces("abcXYZ123!@#") == "abcXYZ123!@#"
    assert fix_spaces("_") == "_"
    assert fix_spaces("__") == "__"


def test_original_underscores_preserved_without_spaces():
    # No spaces, so nothing should change per spec.
    assert fix_spaces("a___b") == "a___b"
    assert fix_spaces("___") == "___"
    assert fix_spaces("a__b__c") == "a__b__c"


def test_original_underscores_adjacent_to_space_run_preserved():
    # Two literal underscores plus a 3-space run: underscores stay, run -> '-'
    assert fix_spaces("a__   b") == "a__-b"
    assert fix_spaces("___   ___") == "___-___"


def test_output_contains_no_spaces():
    assert " " not in fix_spaces(" a  b   c    d ")
    assert fix_spaces(" a  b   c    d ") == "_a__b-c-d-"


def test_leading_trailing_runs():
    assert fix_spaces("   abc") == "-abc"
    assert fix_spaces("abc   ") == "abc-"
    assert fix_spaces("   ") == "-"
    assert fix_spaces("  abc  ") == "__abc__"


def test_separate_runs_each_mapped():
    assert fix_spaces("a  b   c") == "a__b-c"
    assert fix_spaces("a   b  c    d") == "a-b__c-d"


@given(st.text(alphabet=st.sampled_from(["a", "b", "_", "-", " ", "1"]),
               min_size=0, max_size=20))
def test_reference_model_equivalence(s):
    assert fix_spaces(s) == reference(s)


@given(st.lists(st.integers(min_value=1, max_value=10), min_size=1, max_size=5))
def test_each_space_run_length_maps_correctly(lengths):
    # Build "x<spaces>x<spaces>..." with known run lengths.
    parts = ["x"]
    for L in lengths:
        parts.append(" " * L)
        parts.append("x")
    s = "".join(parts)
    expected_parts = ["x"]
    for L in lengths:
        expected_parts.append("-" if L > 2 else "_" * L)
        expected_parts.append("x")
    assert fix_spaces(s) == "".join(expected_parts)


@given(st.text(alphabet=st.sampled_from(["a", "Z", "_", "-", "!", "1"]),
               min_size=0, max_size=15))
def test_strings_without_spaces_are_fixed_points(s):
    assume(" " not in s)
    assert fix_spaces(s) == s


@given(st.text(alphabet=st.sampled_from(["a", "b", "_", " ", "-"]),
               min_size=0, max_size=15))
def test_idempotence_and_no_spaces_in_output(s):
    first = fix_spaces(s)
    assert " " not in first
    assert fix_spaces(first) == first
